import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as r,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"MoE and Frontier Architectures (Bridge)","description":"MoE decouples parameter count from compute, MLA compresses the KV cache, long context changes retrieval economics — this page gives app engineers positional sense: these architectures explain the \\"why\\" behind API pricing, speed, and context strategy in your selection table; derivations bridge to Learn LLM Chapters 9/20.","frontmatter":{"title":"MoE and Frontier Architectures (Bridge)","description":"MoE decouples parameter count from compute, MLA compresses the KV cache, long context changes retrieval economics — this page gives app engineers positional sense: these architectures explain the \\"why\\" behind API pricing, speed, and context strategy in your selection table; derivations bridge to Learn LLM Chapters 9/20.","domain":"tech","tags":["tech","moe","architecture","bridge","long-context"],"navOrder":93,"topicId":"moe-frontier","layer":"9","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/"}],"lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/09-advanced/moe-frontier.md","filePath":"tech/09-advanced/moe-frontier.md","lastUpdated":1791165915000}'),a={name:"tech/09-advanced/moe-frontier.md"};function i(s,e,l,d,c,h){return r(),o("div",null,[...e[0]||(e[0]=[n('<blockquote><p><strong>Group</strong>: Advanced (bridge) | <strong>Previous group exit</strong>: run long-term with release gates and versioning | <strong>This page exit</strong>: know which engineering decision this topic affects, and when to go to Learn LLM</p></blockquote><h1 id="moe-and-frontier-architectures-bridge" tabindex="-1">MoE and Frontier Architectures (Bridge) <a class="header-anchor" href="#moe-and-frontier-architectures-bridge" aria-label="Permalink to &quot;MoE and Frontier Architectures (Bridge)&quot;">​</a></h1><blockquote><p><strong>Bridge page</strong>: MoE routing, load balancing, MLA attention derivations, and long-context position encodings live in <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> (Chapter 9 · Inference and Quantization; Chapter 20 · DeepSeek topic). This repo keeps only the application-side positional sense: <strong>these architectures explain the &quot;why&quot; behind the price, speed, and context caps in your selection table.</strong></p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>What problem it solves</strong>: three frontier directions each break an old equation:</p><ul><li><strong>MoE</strong> (Mixture-of-Experts) breaks &quot;more parameters = more compute per token&quot;: total parameters can be huge while each token activates only a small set of experts — capacity and per-call cost decouple.</li><li><strong>MLA</strong> (Multi-head Latent Attention) breaks &quot;long context = linear KV-cache explosion&quot;: compressing KV into a low-dimensional latent space flattens the inference-cost curve for long contexts.</li><li><strong>Long context</strong> breaks &quot;the model can only see a small window at once&quot;: but &quot;fits in the window&quot; does not mean &quot;used well&quot; — utilization of information in the middle of long inputs has a known degradation shape.</li></ul><p><strong>Why app engineers need positional sense</strong>: you do not need to derive MLA, but the answers to &quot;why is this vendor cheap&quot;, &quot;why is that one fast&quot;, and &quot;how full should I pack the context&quot; all come from these three lines. Without them, selection degenerates into memorizing a price list.</p><h2 id="_2-usage" tabindex="-1">2. Usage <a class="header-anchor" href="#_2-usage" aria-label="Permalink to &quot;2. Usage&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decision</th><th>The positional sense the architecture gives</th></tr></thead><tbody><tr><td>API selection (price/speed)</td><td>an MoE model&#39;s per-token cost is set by <strong>activated parameters</strong>, not total parameters — &quot;huge total parameter count&quot; is not a reason it&#39;s expensive, &quot;large activated parameters&quot; is; hosted APIs have already folded this into pricing</td></tr><tr><td>Hosted vs self-hosted</td><td>MoE saves compute, not memory: all expert weights must stay resident. The self-hosting gate for MoE is memory and communication, not FLOPs — one source of the &quot;hosted is cheap, self-hosted is expensive&quot; paradox</td></tr><tr><td>Context strategy</td><td>long context is not a free RAG replacement: a full window costs real money and mid-window utilization degrades. The doctrine stands — &quot;what retrieval should do, leave to retrieval&quot; (→ <a href="./../04-grounding/">04-grounding</a>); use long windows for what <strong>must be present in full</strong> (entire contracts, long code files)</td></tr><tr><td>KV-cache-related costs</td><td>cache hits and prefix reuse (prompt caching) vary by architecture; for long-context multi-turn workloads, keeping prefixes stable is an engineering money-saver (→ <a href="./../08-production/cost-performance.html">Cost and Performance</a>)</td></tr></tbody></table><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><p>(Deliberately minimal: derivations belong to Learn LLM.)</p><ul><li><strong>MoE</strong> in one line: a router picks a few experts per token — capacity grows, per-call compute doesn&#39;t; the price is load balancing and routing stability.</li><li><strong>MLA</strong> in one line: compress KV into a low-dimensional latent representation and restore on demand — an extension of the MQA/GQA compression line.</li><li><strong>Long context</strong> in one line: windows can grow, but mid-window utilization degrades (the lost-in-the-middle phenomenon) — where you place information inside the context remains an engineering variable.</li></ul><p>Deep water: Learn LLM Chapter 9 (KV cache, MQA/GQA), Chapter 20 (DeepSeek topic: MLA/MoE/GRPO).</p><h2 id="_4-development" tabindex="-1">4. Development <a class="header-anchor" href="#_4-development" aria-label="Permalink to &quot;4. Development&quot;">​</a></h2><p><strong>Symptom → where to go</strong>:</p><ul><li>&quot;Switched to a supposedly stronger model and the bill changed&quot; → recompute unit cost through the activated-parameter lens (→ <a href="./../08-production/cost-performance.html">Cost and Performance</a>).</li><li>&quot;Do we still need RAG with million-token models&quot; → yes. Grounding for private/fresh facts does not vanish with bigger windows (→ <a href="./../04-grounding/">04-grounding</a>); long windows change what is feasible for &quot;present in full&quot; scenarios.</li><li>&quot;Key information in the middle of long documents keeps getting missed&quot; → placement strategy: critical facts at the head or tail, or structured chunking plus retrieval — do not count on uniform attention across a full window.</li><li>Want the routing/MLA derivations → Learn LLM Chapters 9 and 20.</li></ul><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><p>Primary sources (identifiers only; no content re-narrated):</p><table tabindex="0"><thead><tr><th>Name</th><th>Origin</th><th>Identifier</th></tr></thead><tbody><tr><td>Outrageously Large Neural Networks (sparse MoE origin)</td><td>Shazeer et al.</td><td>arXiv:1701.06538</td></tr><tr><td>Switch Transformers (Top-1 routing)</td><td>Fedus / Zoph / Shazeer</td><td>arXiv:2101.03961</td></tr><tr><td>Mixtral of Experts (open MoE representative)</td><td>Mistral AI</td><td>arXiv:2401.04088</td></tr><tr><td>DeepSeek-V2 (introduces MLA)</td><td>DeepSeek-AI</td><td>arXiv:2405.04434</td></tr><tr><td>DeepSeek-V3 Technical Report</td><td>DeepSeek-AI</td><td>arXiv:2412.19437</td></tr><tr><td>Lost in the Middle (long-context position effects)</td><td>Liu et al.</td><td>arXiv:2307.03172</td></tr></tbody></table><p>(retrievedAt 2026-09-01; current architectural details of each model follow its technical report and official docs.)</p><h3 id="where-learn-ai-stops-where-to-go-next" tabindex="-1">Where learn-ai stops / where to go next <a class="header-anchor" href="#where-learn-ai-stops-where-to-go-next" aria-label="Permalink to &quot;Where learn-ai stops / where to go next&quot;">​</a></h3><ul><li>MoE/MLA/GRPO derivations and toy reproductions: <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> Chapter 20 (DeepSeek topic), prerequisite Chapter 9 (Inference and Quantization).</li><li>Context-engineering landing points: <a href="./../03-context/">03-context</a>; cost closure: <a href="./../08-production/">08-production</a>.</li></ul>',22)])])}const b=t(a,[["render",i]]);export{f as __pageData,b as default};
